// 无公开品牌图标：用内置图标保持每个服务商都有可识别标记
const LUCIDE_ICONS: Record<string, string> = {
	"ant-ling": "bug",
	"baseten": "box",
	"cerebras": "cpu",
	"fireworks": "sparkles",
	"groq": "zap",
	"opencode": "terminal",
	"opencode-go": "terminal",
	"radius": "circle-dot",
	"together": "users",
	"typesafe": "shield-check",
};

export function providerIcon(providerId: string): ProviderIcon | undefined {
	return BRAND_ICONS[providerId] ?? (LUCIDE_ICONS[providerId] ? { icon: LUCIDE_ICONS[providerId] } : undefined);
}
